resource teamBudget 'Microsoft.Consumption/budgets@2023-11-01' = {
  name: 'budget-team-checkout'
  properties: {
    category: 'Cost'
    amount: 5000
    timeGrain: 'Monthly'
    timePeriod: { startDate: '2024-01-01' }
    filter: {
      tags: { name: 'costCenter', value: 'CC-4471' }
    }
    notifications: {
      at75: {
        enabled: true
        operator: 'GreaterThanOrEqualTo'
        threshold: 75
        contactEmails: [ 'checkout-team@example.com' ]
      }
      at100: {
        enabled: true
        operator: 'GreaterThanOrEqualTo'
        threshold: 100
        contactEmails: [ 'checkout-team@example.com', 'finops@example.com' ]
      }
    }
  }
}
